import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { toast } from 'react-toastify';
import { FiYoutube, FiEye, FiEyeOff, FiLogIn } from 'react-icons/fi';
import { FaTiktok, FaInstagram } from 'react-icons/fa';
import './Login.css';

export default function Login() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [form, setForm] = useState({ username: '', password: '' });
  const [loading, setLoading] = useState(false);
  const [showPass, setShowPass] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.username || !form.password) {
      toast.error('সব ফিল্ড পূরণ করুন');
      return;
    }
    setLoading(true);
    try {
      await login(form.username, form.password);
      toast.success('স্বাগতম! 🎉');
      navigate('/');
    } catch (err) {
      toast.error(err.response?.data?.error || 'লগইন ব্যর্থ হয়েছে');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-bg">
      <div className="login-glow glow1" />
      <div className="login-glow glow2" />

      <div className="login-card animate-fadein">
        <div className="login-logo">
          <span style={{ color: '#FF0000' }}><FiYoutube size={28} /></span>
          <span style={{ color: '#E1306C' }}><FaInstagram size={26} /></span>
          <span style={{ color: '#69C9D0' }}><FaTiktok size={24} /></span>
        </div>
        <h1 className="login-title gradient-text">SocialHub</h1>
        <p className="login-sub">Multi-Platform Social Media Manager</p>

        <form className="login-form" onSubmit={handleSubmit}>
          <div className="form-group">
            <label>ইউজারনেম</label>
            <input
              type="text"
              placeholder="admin"
              value={form.username}
              onChange={e => setForm(f => ({ ...f, username: e.target.value }))}
              className="input"
              autoComplete="username"
            />
          </div>
          <div className="form-group">
            <label>পাসওয়ার্ড</label>
            <div className="input-wrap">
              <input
                type={showPass ? 'text' : 'password'}
                placeholder="••••••••"
                value={form.password}
                onChange={e => setForm(f => ({ ...f, password: e.target.value }))}
                className="input"
                autoComplete="current-password"
              />
              <button type="button" className="eye-btn" onClick={() => setShowPass(s => !s)}>
                {showPass ? <FiEyeOff /> : <FiEye />}
              </button>
            </div>
          </div>

          <button type="submit" className="btn-primary w-full" disabled={loading}>
            {loading ? (
              <span className="animate-spin">⏳</span>
            ) : (
              <><FiLogIn /> লগইন করুন</>
            )}
          </button>

          <button
            type="button"
            className="btn-outline w-full"
            style={{ borderColor: 'var(--primary)', color: 'var(--primary-light)' }}
            disabled={loading}
            onClick={async () => {
              setLoading(true);
              try {
                await login('admin', 'admin123');
                toast.success('স্বাগতম! 🎉');
                navigate('/');
              } finally {
                setLoading(false);
              }
            }}
          >
            🚀 সরাসরি ডেমো প্রবেশ করুন
          </button>
        </form>

        <div className="login-hint">
          <span className="text-muted text-sm">ডিফল্ট: </span>
          <code>admin</code> / <code>admin123</code>
        </div>
      </div>
    </div>
  );
}
