import React, { useEffect, useState, useCallback } from 'react';
import { useApi } from '../hooks/useApi';
import { toast } from 'react-toastify';
import { FiList, FiTrash2, FiRefreshCw, FiYoutube, FiChevronDown, FiChevronUp } from 'react-icons/fi';
import { FaTiktok, FaInstagram } from 'react-icons/fa';
import { format } from 'date-fns';
import './History.css';

const PLATFORM_CFG = {
  youtube: { icon: <FiYoutube />, color: '#FF0000' },
  instagram: { icon: <FaInstagram />, color: '#E1306C' },
  tiktok: { icon: <FaTiktok />, color: '#69C9D0' },
};

function PostCard({ post, onDelete }) {
  const [expanded, setExpanded] = useState(false);
  const statusColor = { published: '#43E97B', partial: '#FFD93D', failed: '#FF6584', publishing: '#6C63FF' };
  const statusLabel = { published: '✅ সফল', partial: '⚠️ আংশিক', failed: '❌ ব্যর্থ', publishing: '🔄 হচ্ছে' };

  return (
    <div className={`history-card ${post.status}`}>
      <div className="history-card-main">
        <div className="history-left">
          <div className="history-title">{post.title}</div>
          <div className="history-meta">
            <span className="status-badge" style={{ color: statusColor[post.status], borderColor: `${statusColor[post.status]}44`, background: `${statusColor[post.status]}15` }}>
              {statusLabel[post.status] || post.status}
            </span>
            {post.publishedAt && (
              <span className="text-xs text-muted">
                {format(new Date(post.publishedAt), 'dd MMM yyyy, hh:mm a')}
              </span>
            )}
            <span className="text-xs text-muted">{post.accountIds?.length} অ্যাকাউন্ট</span>
          </div>
          {post.tags?.length > 0 && (
            <div className="tags-row mt-1">
              {post.tags.slice(0, 5).map(t => (
                <span key={t} className="tag">#{t}</span>
              ))}
            </div>
          )}
        </div>

        <div className="history-right">
          <div className="platform-results">
            {post.results?.map((r, i) => {
              const cfg = PLATFORM_CFG[r.type] || {};
              return (
                <span key={i} title={`${r.accountName}: ${r.status === 'success' ? 'সফল' : r.error}`}
                  style={{ color: cfg.color }}>
                  {r.status === 'success' ? cfg.icon : <span style={{ color: '#FF6584' }}>⚠</span>}
                </span>
              );
            })}
          </div>
          <button className="icon-btn" onClick={() => setExpanded(e => !e)}>
            {expanded ? <FiChevronUp /> : <FiChevronDown />}
          </button>
          <button className="icon-btn danger" onClick={() => onDelete(post.id, post.title)}>
            <FiTrash2 />
          </button>
        </div>
      </div>

      {expanded && post.results && (
        <div className="history-details animate-fadein">
          {post.results.map((r, i) => (
            <div key={i} className={`result-row ${r.status}`}>
              <span>{r.type && PLATFORM_CFG[r.type]?.icon} {r.accountName}</span>
              <span className={r.status === 'success' ? 'text-success' : 'text-danger'}>
                {r.status === 'success' ? '✅ সফল' : `❌ ${r.error || 'ব্যর্থ'}`}
              </span>
              {r.data?.url && <a href={r.data.url} target="_blank" rel="noopener noreferrer" className="link">🔗 দেখুন</a>}
            </div>
          ))}
          {post.description && (
            <div className="history-desc mt-2 text-muted text-sm">
              {post.description.slice(0, 300)}{post.description.length > 300 ? '...' : ''}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default function History() {
  const api = useApi();
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);

  const fetch = useCallback(() => {
    setLoading(true);
    const params = new URLSearchParams({ page, limit: 20 });
    if (filter !== 'all') params.set('status', filter);
    api.get(`/posts?${params}`)
      .then(r => { setPosts(r.data.posts); setTotal(r.data.total); })
      .catch(() => toast.error('লোড ব্যর্থ'))
      .finally(() => setLoading(false));
  }, [api, filter, page]);

  useEffect(() => { fetch(); }, [fetch]);

  const handleDelete = async (id, title) => {
    if (!window.confirm(`"${title}" মুছবেন?`)) return;
    try {
      await api.delete(`/posts/${id}`);
      toast.success('মুছা হয়েছে');
      fetch();
    } catch { toast.error('মুছতে সমস্যা'); }
  };

  return (
    <div className="history-page animate-fadein">
      <div className="page-header">
        <div>
          <h1 className="page-title">পোস্ট হিস্ট্রি</h1>
          <p className="text-muted">মোট {total}টি পোস্ট</p>
        </div>
        <button className="btn-outline" onClick={fetch}><FiRefreshCw /> রিফ্রেশ</button>
      </div>

      <div className="filter-row">
        {[
          { key: 'all', label: 'সব' },
          { key: 'published', label: '✅ সফল' },
          { key: 'partial', label: '⚠️ আংশিক' },
          { key: 'failed', label: '❌ ব্যর্থ' },
        ].map(f => (
          <button key={f.key} className={`filter-chip ${filter === f.key ? 'active' : ''}`}
            style={{ '--c': '#6C63FF' }}
            onClick={() => { setFilter(f.key); setPage(1); }}>
            {f.label}
          </button>
        ))}
      </div>

      {loading ? (
        <div className="loading-center"><div className="spinner" /></div>
      ) : posts.length === 0 ? (
        <div className="empty-state section-card">
          <FiList size={48} style={{ opacity: 0.3 }} />
          <p>কোনো পোস্ট নেই</p>
          <a href="/create" className="btn-outline">প্রথম পোস্ট করুন</a>
        </div>
      ) : (
        <>
          <div className="history-list">
            {posts.map(p => <PostCard key={p.id} post={p} onDelete={handleDelete} />)}
          </div>
          {total > 20 && (
            <div className="pagination">
              <button className="btn-outline" disabled={page <= 1} onClick={() => setPage(p => p - 1)}>← আগে</button>
              <span className="text-muted">পৃষ্ঠা {page}</span>
              <button className="btn-outline" disabled={page * 20 >= total} onClick={() => setPage(p => p + 1)}>পরে →</button>
            </div>
          )}
        </>
      )}
    </div>
  );
}
