// Client-side Fallback Storage for Offline & GitHub Pages
const STORAGE_PREFIX = 'socialhub_';

function getStored(key, defaultVal) {
  try {
    const item = localStorage.getItem(STORAGE_PREFIX + key);
    return item ? JSON.parse(item) : defaultVal;
  } catch {
    return defaultVal;
  }
}

function setStored(key, val) {
  try {
    localStorage.setItem(STORAGE_PREFIX + key, JSON.stringify(val));
  } catch (e) {
    console.error('Storage error:', e);
  }
}

// Generate UUID
function uid() {
  return 'id_' + Math.random().toString(36).substr(2, 9) + Date.now().toString(36);
}

// Initialize default data if empty
export function initMockData() {
  const accounts = getStored('accounts', null);
  if (!accounts || accounts.length === 0) {
    const initialAccounts = [];
    for (let i = 1; i <= 12; i++) {
      initialAccounts.push({
        id: 'yt_' + i,
        type: 'youtube',
        name: `YouTube Channel ${i}`,
        username: `channel_${i}`,
        connected: true,
        manual: true,
        createdAt: new Date().toISOString()
      });
    }
    for (let i = 1; i <= 2; i++) {
      initialAccounts.push({
        id: 'ig_' + i,
        type: 'instagram',
        name: `Instagram Page ${i}`,
        username: `page_${i}`,
        connected: true,
        manual: true,
        createdAt: new Date().toISOString()
      });
    }
    initialAccounts.push({
      id: 'tt_1',
      type: 'tiktok',
      name: 'TikTok Main Account',
      username: 'tiktok_main',
      connected: true,
      manual: true,
      createdAt: new Date().toISOString()
    });
    setStored('accounts', initialAccounts);
  }

  if (!getStored('posts', null)) setStored('posts', []);
  if (!getStored('scheduled', null)) setStored('scheduled', []);
  if (!getStored('uploads', null)) setStored('uploads', []);
}

// Fallback Request Handler
export async function handleMockApi(config) {
  initMockData();
  const url = (config.url || '').replace(/^[a-z]+:\/\/[^/]+/i, '').replace(/^\/api/, '');
  const method = (config.method || 'get').toLowerCase();

  let body = {};
  if (config.data) {
    try {
      body = typeof config.data === 'string' ? JSON.parse(config.data) : config.data;
    } catch {
      body = config.data;
    }
  }

  // 1. Auth Login
  if (url === '/auth/login' && method === 'post') {
    const username = body.username || 'admin';
    const fakeToken = 'mock_jwt_token_' + Date.now();
    return {
      token: fakeToken,
      user: { id: 'u_1', username, email: `${username}@socialhub.com` }
    };
  }

  // 2. Dashboard
  if (url === '/dashboard' && method === 'get') {
    const accounts = getStored('accounts', []);
    const posts = getStored('posts', []);
    const scheduled = getStored('scheduled', []);
    const uploads = getStored('uploads', []);

    const now = new Date();
    const platformStats = {
      youtube: accounts.filter(a => a.type === 'youtube').length,
      instagram: accounts.filter(a => a.type === 'instagram').length,
      tiktok: accounts.filter(a => a.type === 'tiktok').length,
    };

    const postStats = {
      total: posts.length,
      published: posts.filter(p => p.status === 'published').length,
      partial: posts.filter(p => p.status === 'partial').length,
      failed: posts.filter(p => p.status === 'failed').length,
      lastWeek: posts.length
    };

    const upcomingScheduled = scheduled
      .filter(s => s.status === 'pending' && new Date(s.scheduledAt) > now)
      .slice(0, 5);

    return {
      totalAccounts: accounts.length,
      platformStats,
      postStats,
      totalUploads: uploads.length,
      totalScheduled: scheduled.filter(s => s.status === 'pending').length,
      upcomingScheduled,
      recentActivity: posts.slice(0, 10)
    };
  }

  // 3. Accounts List
  if (url === '/accounts' && method === 'get') {
    const accounts = getStored('accounts', []);
    return { accounts };
  }

  // 4. Add Manual Account
  if (url === '/auth/add-manual' && method === 'post') {
    const accounts = getStored('accounts', []);
    const newAcc = {
      id: uid(),
      type: body.type || 'youtube',
      name: body.name || 'New Account',
      username: body.username || body.name,
      connected: true,
      manual: true,
      createdAt: new Date().toISOString()
    };
    accounts.push(newAcc);
    setStored('accounts', accounts);
    return { account: newAcc };
  }

  // 5. Update Account
  if (url.startsWith('/accounts/') && method === 'put') {
    const id = url.split('/')[2];
    const accounts = getStored('accounts', []);
    const acc = accounts.find(a => a.id === id);
    if (acc && body.name) acc.name = body.name;
    setStored('accounts', accounts);
    return { message: 'Updated' };
  }

  // 6. Delete Account
  if (url.startsWith('/accounts/') && method === 'delete') {
    const id = url.split('/')[2];
    let accounts = getStored('accounts', []);
    accounts = accounts.filter(a => a.id !== id);
    setStored('accounts', accounts);
    return { message: 'Account removed' };
  }

  // 7. Posts List
  if (url.startsWith('/posts') && method === 'get') {
    const posts = getStored('posts', []);
    return { posts, total: posts.length, page: 1, limit: 50 };
  }

  // 8. Publish Post
  if (url === '/posts/publish' && method === 'post') {
    const posts = getStored('posts', []);
    const accounts = getStored('accounts', []);
    const accountIds = body.accountIds || [];

    const results = accountIds.map(id => {
      const acc = accounts.find(a => a.id === id) || { name: 'Account', type: 'youtube' };
      return {
        accountId: id,
        accountName: acc.name,
        type: acc.type,
        status: 'success',
        data: { url: '#' }
      };
    });

    const newPost = {
      id: uid(),
      title: body.title,
      description: body.description || '',
      tags: body.tags || [],
      accountIds,
      videoPath: body.videoPath || null,
      status: 'published',
      results,
      createdAt: new Date().toISOString(),
      publishedAt: new Date().toISOString()
    };

    posts.unshift(newPost);
    setStored('posts', posts);
    return { post: newPost, results };
  }

  // 9. Delete Post
  if (url.startsWith('/posts/') && method === 'delete') {
    const id = url.split('/')[2];
    let posts = getStored('posts', []);
    posts = posts.filter(p => p.id !== id);
    setStored('posts', posts);
    return { message: 'Post deleted' };
  }

  // 10. Schedule List
  if (url.startsWith('/schedule') && method === 'get') {
    const scheduled = getStored('scheduled', []);
    return { scheduled };
  }

  // 11. Create Schedule
  if (url === '/schedule' && method === 'post') {
    const scheduled = getStored('scheduled', []);
    const item = {
      id: uid(),
      title: body.title,
      description: body.description || '',
      tags: body.tags || [],
      accountIds: body.accountIds || [],
      videoPath: body.videoPath || null,
      scheduledAt: body.scheduledAt,
      status: 'pending',
      createdAt: new Date().toISOString()
    };
    scheduled.push(item);
    setStored('scheduled', scheduled);
    return { scheduled: item };
  }

  // 12. Update Schedule
  if (url.startsWith('/schedule/') && method === 'put') {
    const id = url.split('/')[2];
    const scheduled = getStored('scheduled', []);
    const item = scheduled.find(s => s.id === id);
    if (item) {
      if (body.title) item.title = body.title;
      if (body.description !== undefined) item.description = body.description;
      if (body.scheduledAt) item.scheduledAt = body.scheduledAt;
    }
    setStored('scheduled', scheduled);
    return { scheduled: item };
  }

  // 13. Delete Schedule
  if (url.startsWith('/schedule/') && method === 'delete') {
    const id = url.split('/')[2];
    let scheduled = getStored('scheduled', []);
    scheduled = scheduled.filter(s => s.id !== id);
    setStored('scheduled', scheduled);
    return { message: 'Deleted' };
  }

  // 14. Upload Files
  if (url === '/upload' && method === 'post') {
    const uploads = getStored('uploads', []);
    const newFiles = [
      {
        id: uid(),
        originalName: 'uploaded_video_' + Date.now() + '.mp4',
        filename: 'vid_' + Date.now() + '.mp4',
        path: '/uploads/sample.mp4',
        size: 15 * 1024 * 1024,
        mimetype: 'video/mp4',
        uploadedAt: new Date().toISOString()
      }
    ];
    uploads.unshift(...newFiles);
    setStored('uploads', uploads);
    return { files: newFiles };
  }

  // 15. Get Uploads
  if (url === '/upload' && method === 'get') {
    const uploads = getStored('uploads', []);
    return { files: uploads };
  }

  // 16. Delete Upload
  if (url.startsWith('/upload/') && method === 'delete') {
    const id = url.split('/')[2];
    let uploads = getStored('uploads', []);
    uploads = uploads.filter(u => u.id !== id);
    setStored('uploads', uploads);
    return { message: 'File deleted' };
  }

  return null;
}
