import React, { useEffect, useState, useCallback } from 'react';
import { useSearchParams } from 'react-router-dom';
import { useApi } from '../hooks/useApi';
import { toast } from 'react-toastify';
import { FiYoutube, FiPlus, FiTrash2, FiEdit2, FiCheck, FiX, FiRefreshCw } from 'react-icons/fi';
import { FaTiktok, FaInstagram } from 'react-icons/fa';
import './Accounts.css';

const PLATFORM_CFG = {
  youtube: { icon: <FiYoutube />, color: '#FF0000', label: 'YouTube' },
  instagram: { icon: <FaInstagram />, color: '#E1306C', label: 'Instagram' },
  tiktok: { icon: <FaTiktok />, color: '#69C9D0', label: 'TikTok' },
};

function AccountCard({ account, onDelete, onRename }) {
  const cfg = PLATFORM_CFG[account.type] || {};
  const [editing, setEditing] = useState(false);
  const [name, setName] = useState(account.name);

  const saveRename = async () => {
    if (name.trim()) {
      await onRename(account.id, name.trim());
      setEditing(false);
    }
  };

  return (
    <div className="account-card animate-fadein">
      <div className="account-platform-icon" style={{ color: cfg.color, background: `${cfg.color}18` }}>
        {cfg.icon}
      </div>
      <div className="account-info">
        {editing ? (
          <div className="rename-row">
            <input
              className="input rename-input"
              value={name}
              onChange={e => setName(e.target.value)}
              autoFocus
              onKeyDown={e => { if (e.key === 'Enter') saveRename(); if (e.key === 'Escape') setEditing(false); }}
            />
            <button className="icon-btn success" onClick={saveRename}><FiCheck /></button>
            <button className="icon-btn danger" onClick={() => setEditing(false)}><FiX /></button>
          </div>
        ) : (
          <div className="account-name">{account.name}</div>
        )}
        <div className="account-meta">
          <span className="platform-tag" style={{ color: cfg.color, borderColor: `${cfg.color}44`, background: `${cfg.color}15` }}>
            {cfg.icon} {cfg.label}
          </span>
          {account.username && <span className="text-muted text-xs">@{account.username}</span>}
          {account.email && <span className="text-muted text-xs">{account.email}</span>}
          {account.manual && <span className="manual-badge">Manual</span>}
        </div>
      </div>
      <div className="account-actions">
        <button className="icon-btn" onClick={() => setEditing(true)} title="নাম পরিবর্তন">
          <FiEdit2 />
        </button>
        <button className="icon-btn danger" onClick={() => onDelete(account.id, account.name)} title="মুছুন">
          <FiTrash2 />
        </button>
      </div>
    </div>
  );
}

function AddManualModal({ onClose, onAdd }) {
  const [form, setForm] = useState({ type: 'youtube', name: '', username: '' });
  const [loading, setLoading] = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    if (!form.name) return toast.error('নাম দিন');
    setLoading(true);
    await onAdd(form);
    setLoading(false);
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal animate-fadein" onClick={e => e.stopPropagation()}>
        <div className="modal-header">
          <h3>অ্যাকাউন্ট যোগ করুন</h3>
          <button className="icon-btn" onClick={onClose}><FiX /></button>
        </div>
        <form onSubmit={submit}>
          <div className="form-group mt-2">
            <label>প্ল্যাটফর্ম</label>
            <select className="input" value={form.type} onChange={e => setForm(f => ({ ...f, type: e.target.value }))}>
              <option value="youtube">YouTube</option>
              <option value="instagram">Instagram</option>
              <option value="tiktok">TikTok</option>
            </select>
          </div>
          <div className="form-group mt-2">
            <label>চ্যানেল / পেজের নাম *</label>
            <input className="input" placeholder="যেমন: My Gaming Channel" value={form.name}
              onChange={e => setForm(f => ({ ...f, name: e.target.value }))} />
          </div>
          <div className="form-group mt-2">
            <label>ইউজারনেম (ঐচ্ছিক)</label>
            <input className="input" placeholder="@username" value={form.username}
              onChange={e => setForm(f => ({ ...f, username: e.target.value }))} />
          </div>
          <div className="modal-actions mt-3">
            <button type="button" className="btn-outline" onClick={onClose}>বাতিল</button>
            <button type="submit" className="btn-primary" disabled={loading}>
              {loading ? '...' : 'যোগ করুন'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

export default function Accounts() {
  const api = useApi();
  const [searchParams] = useSearchParams();
  const [accounts, setAccounts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [showAdd, setShowAdd] = useState(false);

  const fetchAccounts = useCallback(() => {
    setLoading(true);
    api.get('/accounts')
      .then(r => setAccounts(r.data.accounts))
      .catch(() => toast.error('অ্যাকাউন্ট লোড ব্যর্থ'))
      .finally(() => setLoading(false));
  }, [api]);

  useEffect(() => {
    fetchAccounts();
    const connected = searchParams.get('connected');
    const error = searchParams.get('error');
    if (connected) toast.success(`${connected} অ্যাকাউন্ট সংযুক্ত হয়েছে! 🎉`);
    if (error) toast.error(`সংযোগ ব্যর্থ: ${error}`);
  }, [fetchAccounts, searchParams]);

  const handleDelete = async (id, name) => {
    if (!window.confirm(`"${name}" অ্যাকাউন্ট মুছবেন?`)) return;
    try {
      await api.delete(`/accounts/${id}`);
      toast.success('অ্যাকাউন্ট মুছা হয়েছে');
      fetchAccounts();
    } catch { toast.error('মুছতে সমস্যা হয়েছে'); }
  };

  const handleRename = async (id, name) => {
    try {
      await api.put(`/accounts/${id}`, { name });
      toast.success('নাম আপডেট হয়েছে');
      setAccounts(acc => acc.map(a => a.id === id ? { ...a, name } : a));
    } catch { toast.error('আপডেট ব্যর্থ'); }
  };

  const handleOAuthConnect = async (type) => {
    try {
      const r = await api.get(`/auth/${type}/connect`);
      window.open(r.data.url, '_blank', 'width=600,height=700');
    } catch { toast.error('OAuth URL তৈরি ব্যর্থ — API keys সেট করুন'); }
  };

  const handleManualAdd = async (form) => {
    try {
      await api.post('/auth/add-manual', form);
      toast.success('অ্যাকাউন্ট যোগ হয়েছে');
      fetchAccounts();
      setShowAdd(false);
    } catch { toast.error('যোগ করতে সমস্যা'); }
  };

  const filtered = filter === 'all' ? accounts : accounts.filter(a => a.type === filter);

  const stats = {
    youtube: accounts.filter(a => a.type === 'youtube').length,
    instagram: accounts.filter(a => a.type === 'instagram').length,
    tiktok: accounts.filter(a => a.type === 'tiktok').length,
  };

  return (
    <div className="accounts-page animate-fadein">
      <div className="page-header">
        <div>
          <h1 className="page-title">অ্যাকাউন্টস</h1>
          <p className="text-muted">আপনার সব সোশ্যাল মিডিয়া অ্যাকাউন্ট ম্যানেজ করুন</p>
        </div>
        <div className="header-actions">
          <button className="btn-outline" onClick={fetchAccounts}><FiRefreshCw /> রিফ্রেশ</button>
          <button className="btn-primary" onClick={() => setShowAdd(true)}><FiPlus /> অ্যাকাউন্ট যোগ</button>
        </div>
      </div>

      {/* OAuth Connect section */}
      <div className="connect-section">
        <h3 className="section-title">🔗 OAuth দিয়ে সংযুক্ত করুন</h3>
        <p className="text-muted text-sm mb-2">API keys সেট করলে সরাসরি লগইন করতে পারবেন</p>
        <div className="connect-btns">
          <button className="connect-btn youtube" onClick={() => handleOAuthConnect('youtube')}>
            <FiYoutube /> YouTube সংযুক্ত করুন
          </button>
          <button className="connect-btn instagram" onClick={() => handleOAuthConnect('instagram')}>
            <FaInstagram /> Instagram সংযুক্ত করুন
          </button>
          <button className="connect-btn tiktok" onClick={() => handleOAuthConnect('tiktok')}>
            <FaTiktok /> TikTok সংযুক্ত করুন
          </button>
        </div>
      </div>

      {/* Stats */}
      <div className="acc-stats">
        {[
          { key: 'all', label: 'সব', count: accounts.length, color: '#6C63FF' },
          { key: 'youtube', label: 'YouTube', count: stats.youtube, color: '#FF0000' },
          { key: 'instagram', label: 'Instagram', count: stats.instagram, color: '#E1306C' },
          { key: 'tiktok', label: 'TikTok', count: stats.tiktok, color: '#69C9D0' },
        ].map(s => (
          <button
            key={s.key}
            className={`filter-chip ${filter === s.key ? 'active' : ''}`}
            style={{ '--c': s.color }}
            onClick={() => setFilter(s.key)}
          >
            <span className="chip-count">{s.count}</span>
            {s.label}
          </button>
        ))}
      </div>

      {/* Account list */}
      {loading ? (
        <div className="loading-center"><div className="spinner" /></div>
      ) : filtered.length === 0 ? (
        <div className="empty-state section-card">
          <FiUsers size={48} style={{ opacity: 0.3 }} />
          <p>এখনো কোনো অ্যাকাউন্ট নেই</p>
          <button className="btn-primary" onClick={() => setShowAdd(true)}>
            <FiPlus /> প্রথম অ্যাকাউন্ট যোগ করুন
          </button>
        </div>
      ) : (
        <div className="accounts-grid">
          {filtered.map(acc => (
            <AccountCard
              key={acc.id}
              account={acc}
              onDelete={handleDelete}
              onRename={handleRename}
            />
          ))}
        </div>
      )}

      {showAdd && (
        <AddManualModal onClose={() => setShowAdd(false)} onAdd={handleManualAdd} />
      )}
    </div>
  );
}
