import React, { useEffect, useState, useCallback } from 'react';
import { useApi } from '../hooks/useApi';
import { toast } from 'react-toastify';
import { useDropzone } from 'react-dropzone';
import {
  FiUploadCloud, FiX, FiSend, FiClock, FiYoutube,
  FiPlus, FiMinus, FiCheck, FiVideo, FiImage
} from 'react-icons/fi';
import { FaTiktok, FaInstagram } from 'react-icons/fa';
import DatePicker from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';
import './CreatePost.css';

const PLATFORM_CFG = {
  youtube: { icon: <FiYoutube />, color: '#FF0000', label: 'YouTube' },
  instagram: { icon: <FaInstagram />, color: '#E1306C', label: 'Instagram' },
  tiktok: { icon: <FaTiktok />, color: '#69C9D0', label: 'TikTok' },
};

function FileDropZone({ onFiles, files, onRemove }) {
  const onDrop = useCallback(accepted => onFiles(accepted), [onFiles]);
  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: { 'video/*': ['.mp4', '.mov', '.avi', '.mkv', '.webm'], 'image/*': ['.jpg', '.jpeg', '.png', '.gif', '.webp'] },
    multiple: true,
    maxSize: 500 * 1024 * 1024
  });

  return (
    <div>
      <div {...getRootProps()} className={`dropzone ${isDragActive ? 'active' : ''}`}>
        <input {...getInputProps()} />
        <div className="dropzone-inner">
          <FiUploadCloud size={36} />
          <p>{isDragActive ? 'এখানে ছেড়ে দিন!' : 'ভিডিও / ছবি এখানে টেনে আনুন বা ক্লিক করুন'}</p>
          <span className="text-muted text-xs">MP4, MOV, AVI, MKV, JPG, PNG — সর্বোচ্চ 500MB প্রতি ফাইল</span>
        </div>
      </div>

      {files.length > 0 && (
        <div className="file-list mt-2">
          {files.map((f, i) => (
            <div key={i} className="file-item">
              <span className="file-icon">
                {f.type?.startsWith('video') ? <FiVideo /> : <FiImage />}
              </span>
              <div className="file-info">
                <span className="file-name">{f.name}</span>
                <span className="text-xs text-muted">{(f.size / (1024 * 1024)).toFixed(1)} MB</span>
              </div>
              <button className="icon-btn danger" onClick={() => onRemove(i)}><FiX /></button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function UploadedFileSelector({ onSelect, selected }) {
  const api = useApi();
  const [files, setFiles] = useState([]);
  useEffect(() => {
    api.get('/upload').then(r => setFiles(r.data.files)).catch(() => {});
  }, [api]);

  if (!files.length) return null;
  return (
    <div className="library-selector mt-2">
      <p className="text-sm text-muted mb-1">📁 লাইব্রেরি থেকে বেছে নিন:</p>
      <div className="library-grid">
        {files.slice(0, 12).map(f => (
          <div
            key={f.id}
            className={`library-item ${selected?.id === f.id ? 'selected' : ''}`}
            onClick={() => onSelect(selected?.id === f.id ? null : f)}
          >
            {f.mimetype?.startsWith('video') ? <FiVideo size={20} /> : <FiImage size={20} />}
            <span className="text-xs">{f.originalName?.slice(0, 18)}</span>
            {selected?.id === f.id && <div className="selected-check"><FiCheck /></div>}
          </div>
        ))}
      </div>
    </div>
  );
}

export default function CreatePost() {
  const api = useApi();
  const [accounts, setAccounts] = useState([]);
  const [form, setForm] = useState({
    title: '',
    description: '',
    tags: '',
    selectedAccounts: [],
    isScheduled: false,
    scheduledAt: null,
  });
  const [files, setFiles] = useState([]);
  const [libraryFile, setLibraryFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [results, setResults] = useState(null);

  useEffect(() => {
    api.get('/accounts').then(r => setAccounts(r.data.accounts)).catch(() => {});
  }, [api]);

  const toggleAccount = (id) => {
    setForm(f => ({
      ...f,
      selectedAccounts: f.selectedAccounts.includes(id)
        ? f.selectedAccounts.filter(a => a !== id)
        : [...f.selectedAccounts, id]
    }));
  };

  const selectAll = (type) => {
    const ids = accounts.filter(a => a.type === type).map(a => a.id);
    setForm(f => {
      const allSelected = ids.every(id => f.selectedAccounts.includes(id));
      if (allSelected) return { ...f, selectedAccounts: f.selectedAccounts.filter(id => !ids.includes(id)) };
      return { ...f, selectedAccounts: [...new Set([...f.selectedAccounts, ...ids])] };
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.title.trim()) return toast.error('টাইটেল দিন');
    if (!form.selectedAccounts.length) return toast.error('অন্তত একটি অ্যাকাউন্ট বেছে নিন');
    if (form.isScheduled && !form.scheduledAt) return toast.error('শিডিউল সময় দিন');

    let videoPath = libraryFile?.path || null;

    // Upload new files
    if (files.length > 0) {
      setUploading(true);
      try {
        const formData = new FormData();
        files.forEach(f => formData.append('files', f));
        const uploadRes = await api.post('/upload', formData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
        videoPath = uploadRes.data.files[0]?.path || null;
        toast.success(`${files.length}টি ফাইল আপলোড হয়েছে`);
      } catch { toast.error('আপলোড ব্যর্থ'); return; }
      finally { setUploading(false); }
    }

    setSubmitting(true);
    try {
      const payload = {
        title: form.title,
        description: form.description,
        tags: form.tags.split(',').map(t => t.trim()).filter(Boolean),
        accountIds: form.selectedAccounts,
        videoPath,
      };

      if (form.isScheduled) {
        const r = await api.post('/schedule', {
          ...payload,
          scheduledAt: form.scheduledAt.toISOString()
        });
        toast.success('শিডিউল সফলভাবে সেট হয়েছে! ⏰');
        setResults({ scheduled: r.data.scheduled });
      } else {
        const r = await api.post('/posts/publish', payload);
        const successCount = r.data.results.filter(x => x.status === 'success').length;
        toast.success(`${successCount}/${r.data.results.length} অ্যাকাউন্টে পোস্ট সফল!`);
        setResults({ results: r.data.results });
      }

      setForm(f => ({ ...f, title: '', description: '', tags: '', selectedAccounts: [], isScheduled: false, scheduledAt: null }));
      setFiles([]);
      setLibraryFile(null);
    } catch (err) {
      toast.error(err.response?.data?.error || 'পোস্ট করতে সমস্যা');
    } finally {
      setSubmitting(false);
    }
  };

  const platforms = ['youtube', 'instagram', 'tiktok'];

  return (
    <div className="create-page animate-fadein">
      <div className="page-header">
        <div>
          <h1 className="page-title">নতুন পোস্ট</h1>
          <p className="text-muted">একসাথে সব প্ল্যাটফর্মে পোস্ট করুন</p>
        </div>
      </div>

      <form className="create-form" onSubmit={handleSubmit}>
        <div className="create-layout">
          {/* Left: Content */}
          <div className="create-left">
            {/* Title */}
            <div className="form-card">
              <h3 className="card-title">📝 পোস্টের বিবরণ</h3>
              <div className="form-group">
                <label>টাইটেল *</label>
                <input
                  className="input"
                  placeholder="আপনার ভিডিওর শিরোনাম লিখুন..."
                  value={form.title}
                  onChange={e => setForm(f => ({ ...f, title: e.target.value }))}
                  maxLength={200}
                />
                <span className="char-count">{form.title.length}/200</span>
              </div>

              <div className="form-group mt-2">
                <label>বর্ণনা</label>
                <textarea
                  className="input textarea"
                  placeholder="ভিডিওর বিস্তারিত বর্ণনা লিখুন..."
                  value={form.description}
                  onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
                  rows={5}
                />
              </div>

              <div className="form-group mt-2">
                <label>ট্যাগ (কমা দিয়ে আলাদা করুন)</label>
                <input
                  className="input"
                  placeholder="gaming, funny, viral, trending..."
                  value={form.tags}
                  onChange={e => setForm(f => ({ ...f, tags: e.target.value }))}
                />
              </div>
            </div>

            {/* Media */}
            <div className="form-card">
              <h3 className="card-title">🎬 মিডিয়া</h3>
              <FileDropZone
                files={files}
                onFiles={newFiles => setFiles(prev => [...prev, ...newFiles])}
                onRemove={i => setFiles(prev => prev.filter((_, idx) => idx !== i))}
              />
              <UploadedFileSelector selected={libraryFile} onSelect={setLibraryFile} />
              {libraryFile && (
                <div className="selected-library-file mt-1">
                  <FiCheck className="text-success" /> লাইব্রেরি থেকে: {libraryFile.originalName}
                  <button type="button" className="icon-btn danger" onClick={() => setLibraryFile(null)}><FiX /></button>
                </div>
              )}
            </div>

            {/* Schedule toggle */}
            <div className="form-card">
              <h3 className="card-title">⏰ প্রকাশের সময়</h3>
              <div className="toggle-row">
                <button
                  type="button"
                  className={`toggle-btn ${!form.isScheduled ? 'active' : ''}`}
                  onClick={() => setForm(f => ({ ...f, isScheduled: false }))}
                >
                  <FiSend /> এখনই পোস্ট করুন
                </button>
                <button
                  type="button"
                  className={`toggle-btn ${form.isScheduled ? 'active' : ''}`}
                  onClick={() => setForm(f => ({ ...f, isScheduled: true }))}
                >
                  <FiClock /> শিডিউল করুন
                </button>
              </div>

              {form.isScheduled && (
                <div className="form-group mt-2 animate-fadein">
                  <label>তারিখ ও সময় বেছে নিন</label>
                  <DatePicker
                    selected={form.scheduledAt}
                    onChange={d => setForm(f => ({ ...f, scheduledAt: d }))}
                    showTimeSelect
                    dateFormat="Pp"
                    minDate={new Date()}
                    placeholderText="তারিখ ও সময় বেছে নিন"
                    className="input"
                    wrapperClassName="w-full"
                  />
                </div>
              )}
            </div>
          </div>

          {/* Right: Account selection */}
          <div className="create-right">
            <div className="form-card accounts-selector">
              <h3 className="card-title">📱 অ্যাকাউন্ট বেছে নিন</h3>
              <p className="text-xs text-muted mb-2">
                {form.selectedAccounts.length} টি বেছেছেন
              </p>

              {accounts.length === 0 ? (
                <div className="empty-state">
                  <p className="text-muted text-sm">কোনো অ্যাকাউন্ট নেই।</p>
                  <a href="/accounts" className="btn-outline text-sm">অ্যাকাউন্ট যোগ করুন</a>
                </div>
              ) : (
                platforms.map(type => {
                  const platAccounts = accounts.filter(a => a.type === type);
                  if (!platAccounts.length) return null;
                  const cfg = PLATFORM_CFG[type];
                  const allSelected = platAccounts.every(a => form.selectedAccounts.includes(a.id));
                  return (
                    <div key={type} className="platform-group">
                      <div className="platform-group-header">
                        <span style={{ color: cfg.color }}>{cfg.icon}</span>
                        <span style={{ color: cfg.color }}>{cfg.label} ({platAccounts.length})</span>
                        <button
                          type="button"
                          className="select-all-btn"
                          onClick={() => selectAll(type)}
                          style={{ color: cfg.color }}
                        >
                          {allSelected ? <><FiMinus /> সব বাদ</> : <><FiPlus /> সব বেছে নিন</>}
                        </button>
                      </div>
                      {platAccounts.map(acc => (
                        <div
                          key={acc.id}
                          className={`account-check ${form.selectedAccounts.includes(acc.id) ? 'selected' : ''}`}
                          style={{ '--c': cfg.color }}
                          onClick={() => toggleAccount(acc.id)}
                        >
                          <div className="checkbox">
                            {form.selectedAccounts.includes(acc.id) && <FiCheck />}
                          </div>
                          <span>{acc.name}</span>
                        </div>
                      ))}
                    </div>
                  );
                })
              )}

              <button
                type="submit"
                className="btn-primary w-full mt-3"
                disabled={submitting || uploading}
              >
                {uploading ? '📤 আপলোড হচ্ছে...' :
                 submitting ? '🚀 পোস্ট হচ্ছে...' :
                 form.isScheduled ? <><FiClock /> শিডিউল করুন</> : <><FiSend /> পোস্ট করুন</>}
              </button>
            </div>
          </div>
        </div>
      </form>

      {/* Results */}
      {results && (
        <div className="results-card animate-fadein">
          <h3 className="card-title">
            {results.scheduled ? '✅ শিডিউল সেট হয়েছে' : '📊 পোস্টের ফলাফল'}
          </h3>
          {results.scheduled && (
            <p className="text-muted">শিডিউল করা হয়েছে: <strong>{new Date(results.scheduled.scheduledAt).toLocaleString('bn-BD')}</strong></p>
          )}
          {results.results && (
            <div className="results-list mt-2">
              {results.results.map((r, i) => (
                <div key={i} className={`result-item ${r.status}`}>
                  <span className="result-platform">{r.accountName}</span>
                  <span className="result-status">
                    {r.status === 'success' ? '✅ সফল' : `❌ ${r.error}`}
                  </span>
                </div>
              ))}
            </div>
          )}
          <button className="btn-outline mt-2" onClick={() => setResults(null)}>বন্ধ করুন</button>
        </div>
      )}
    </div>
  );
}
