import React, { useEffect, useState, useCallback } from 'react';
import { useApi } from '../hooks/useApi';
import { toast } from 'react-toastify';
import { FiClock, FiTrash2, FiEdit2, FiX, FiCheck } from 'react-icons/fi';
import { format, isFuture, isPast } from 'date-fns';
import DatePicker from 'react-datepicker';
import './Schedule.css';

function StatusBadge({ status }) {
  const cfg = {
    pending: { label: '⏳ অপেক্ষায়', color: '#FFD93D' },
    publishing: { label: '🚀 পোস্ট হচ্ছে', color: '#6C63FF' },
    published: { label: '✅ প্রকাশিত', color: '#43E97B' },
    partial: { label: '⚠️ আংশিক', color: '#FFD93D' },
    failed: { label: '❌ ব্যর্থ', color: '#FF6584' },
  };
  const c = cfg[status] || { label: status, color: '#8888AA' };
  return (
    <span className="status-badge" style={{ color: c.color, borderColor: `${c.color}44`, background: `${c.color}15` }}>
      {c.label}
    </span>
  );
}

function EditModal({ post, onClose, onSave }) {
  const [form, setForm] = useState({
    title: post.title,
    description: post.description,
    scheduledAt: new Date(post.scheduledAt)
  });
  const [loading, setLoading] = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    setLoading(true);
    await onSave(post.id, { title: form.title, description: form.description, scheduledAt: form.scheduledAt.toISOString() });
    setLoading(false);
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal animate-fadein" onClick={e => e.stopPropagation()}>
        <div className="modal-header">
          <h3>শিডিউল সম্পাদনা</h3>
          <button className="icon-btn" onClick={onClose}><FiX /></button>
        </div>
        <form onSubmit={submit}>
          <div className="form-group mt-2">
            <label>টাইটেল</label>
            <input className="input" value={form.title} onChange={e => setForm(f => ({ ...f, title: e.target.value }))} />
          </div>
          <div className="form-group mt-2">
            <label>বর্ণনা</label>
            <textarea className="input textarea" rows={3} value={form.description}
              onChange={e => setForm(f => ({ ...f, description: e.target.value }))} />
          </div>
          <div className="form-group mt-2">
            <label>তারিখ ও সময়</label>
            <DatePicker
              selected={form.scheduledAt}
              onChange={d => setForm(f => ({ ...f, scheduledAt: d }))}
              showTimeSelect
              dateFormat="Pp"
              minDate={new Date()}
              className="input"
              wrapperClassName="w-full"
            />
          </div>
          <div className="modal-actions mt-3">
            <button type="button" className="btn-outline" onClick={onClose}>বাতিল</button>
            <button type="submit" className="btn-primary" disabled={loading}>{loading ? '...' : 'সেভ করুন'}</button>
          </div>
        </form>
      </div>
    </div>
  );
}

export default function Schedule() {
  const api = useApi();
  const [scheduled, setScheduled] = useState([]);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(null);
  const [filter, setFilter] = useState('all');

  const fetch = useCallback(() => {
    setLoading(true);
    api.get('/schedule')
      .then(r => setScheduled(r.data.scheduled))
      .catch(() => toast.error('লোড ব্যর্থ'))
      .finally(() => setLoading(false));
  }, [api]);

  useEffect(() => { fetch(); }, [fetch]);

  const handleDelete = async (id, title) => {
    if (!window.confirm(`"${title}" শিডিউল মুছবেন?`)) return;
    try {
      await api.delete(`/schedule/${id}`);
      toast.success('মুছা হয়েছে');
      fetch();
    } catch { toast.error('মুছতে সমস্যা'); }
  };

  const handleSave = async (id, data) => {
    try {
      await api.put(`/schedule/${id}`, data);
      toast.success('আপডেট হয়েছে');
      setEditing(null);
      fetch();
    } catch { toast.error('আপডেট ব্যর্থ'); }
  };

  const filters = [
    { key: 'all', label: 'সব' },
    { key: 'pending', label: '⏳ অপেক্ষায়' },
    { key: 'published', label: '✅ প্রকাশিত' },
    { key: 'failed', label: '❌ ব্যর্থ' },
  ];

  const filtered = filter === 'all' ? scheduled : scheduled.filter(s => s.status === filter);

  return (
    <div className="schedule-page animate-fadein">
      <div className="page-header">
        <div>
          <h1 className="page-title">শিডিউল ম্যানেজার</h1>
          <p className="text-muted">আপনার নির্ধারিত পোস্টগুলো দেখুন ও পরিচালনা করুন</p>
        </div>
        <a href="/create" className="btn-primary">নতুন শিডিউল</a>
      </div>

      <div className="schedule-stats">
        <div className="sched-stat">
          <span className="sched-num">{scheduled.filter(s => s.status === 'pending').length}</span>
          <span className="text-muted text-sm">অপেক্ষায়</span>
        </div>
        <div className="sched-stat">
          <span className="sched-num" style={{ color: '#43E97B' }}>{scheduled.filter(s => s.status === 'published').length}</span>
          <span className="text-muted text-sm">প্রকাশিত</span>
        </div>
        <div className="sched-stat">
          <span className="sched-num" style={{ color: '#FF6584' }}>{scheduled.filter(s => s.status === 'failed').length}</span>
          <span className="text-muted text-sm">ব্যর্থ</span>
        </div>
      </div>

      <div className="filter-row">
        {filters.map(f => (
          <button
            key={f.key}
            className={`filter-chip ${filter === f.key ? 'active' : ''}`}
            style={{ '--c': '#6C63FF' }}
            onClick={() => setFilter(f.key)}
          >
            {f.label}
          </button>
        ))}
      </div>

      {loading ? (
        <div className="loading-center"><div className="spinner" /></div>
      ) : filtered.length === 0 ? (
        <div className="empty-state section-card">
          <FiClock size={48} style={{ opacity: 0.3 }} />
          <p>কোনো শিডিউল নেই</p>
          <a href="/create" className="btn-outline">নতুন শিডিউল তৈরি করুন</a>
        </div>
      ) : (
        <div className="schedule-list">
          {filtered.map(s => (
            <div key={s.id} className={`schedule-card ${s.status}`}>
              <div className="schedule-time">
                <FiClock />
                <div>
                  <div className="time-main">{format(new Date(s.scheduledAt), 'dd MMM yyyy')}</div>
                  <div className="time-sub">{format(new Date(s.scheduledAt), 'hh:mm a')}</div>
                </div>
                {isFuture(new Date(s.scheduledAt)) && s.status === 'pending' && (
                  <span className="countdown animate-pulse">🔔 আসছে</span>
                )}
              </div>

              <div className="schedule-info">
                <h4 className="schedule-title">{s.title}</h4>
                {s.description && (
                  <p className="schedule-desc text-muted text-sm">{s.description.slice(0, 100)}{s.description.length > 100 ? '...' : ''}</p>
                )}
                <div className="schedule-meta">
                  <StatusBadge status={s.status} />
                  <span className="text-xs text-muted">{s.accountIds?.length} অ্যাকাউন্ট</span>
                  {s.tags?.length > 0 && (
                    <span className="text-xs text-muted">#{s.tags.slice(0, 3).join(' #')}</span>
                  )}
                </div>
              </div>

              {s.status === 'pending' && (
                <div className="schedule-actions">
                  <button className="icon-btn" onClick={() => setEditing(s)} title="সম্পাদনা">
                    <FiEdit2 />
                  </button>
                  <button className="icon-btn danger" onClick={() => handleDelete(s.id, s.title)} title="মুছুন">
                    <FiTrash2 />
                  </button>
                </div>
              )}

              {s.results && s.status !== 'pending' && (
                <div className="schedule-results">
                  {s.results.map((r, i) => (
                    <span key={i} className={`result-dot ${r.status}`} title={`${r.accountName}: ${r.status}`}>
                      {r.status === 'success' ? '✅' : '❌'}
                    </span>
                  ))}
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {editing && (
        <EditModal post={editing} onClose={() => setEditing(null)} onSave={handleSave} />
      )}
    </div>
  );
}
