import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useApi } from '../hooks/useApi';
import { FiUsers, FiPlusSquare, FiClock, FiFolder, FiTrendingUp, FiCheckCircle, FiAlertCircle } from 'react-icons/fi';
import { FiYoutube } from 'react-icons/fi';
import { FaTiktok, FaInstagram } from 'react-icons/fa';
import { format } from 'date-fns';
import './Dashboard.css';

function StatCard({ icon, label, value, color, to }) {
  const content = (
    <div className="stat-card" style={{ '--accent-color': color }}>
      <div className="stat-icon" style={{ background: `${color}22`, color }}>
        {icon}
      </div>
      <div>
        <div className="stat-value">{value}</div>
        <div className="stat-label">{label}</div>
      </div>
    </div>
  );
  return to ? <Link to={to} style={{ textDecoration: 'none' }}>{content}</Link> : content;
}

function PlatformBadge({ type, count }) {
  const cfg = {
    youtube: { icon: <FiYoutube />, color: '#FF0000', label: 'YouTube' },
    instagram: { icon: <FaInstagram />, color: '#E1306C', label: 'Instagram' },
    tiktok: { icon: <FaTiktok />, color: '#69C9D0', label: 'TikTok' },
  };
  const c = cfg[type] || {};
  return (
    <div className="platform-badge" style={{ '--c': c.color }}>
      <span style={{ color: c.color }}>{c.icon}</span>
      <span>{count}</span>
      <span className="text-muted">{c.label}</span>
    </div>
  );
}

export default function Dashboard() {
  const api = useApi();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.get('/dashboard')
      .then(r => setData(r.data))
      .catch(console.error)
      .finally(() => setLoading(false));
  }, [api]);

  if (loading) return (
    <div className="loading-center">
      <div className="spinner" />
      <p className="text-muted mt-2">লোড হচ্ছে...</p>
    </div>
  );

  return (
    <div className="dashboard animate-fadein">
      <div className="page-header">
        <div>
          <h1 className="page-title">ড্যাশবোর্ড <span className="wave">👋</span></h1>
          <p className="text-muted">আপনার সব সোশ্যাল মিডিয়া একনজরে</p>
        </div>
        <Link to="/create" className="btn-primary">
          <FiPlusSquare /> নতুন পোস্ট
        </Link>
      </div>

      {/* Stats Row */}
      <div className="stats-grid">
        <StatCard icon={<FiUsers />} label="মোট অ্যাকাউন্ট" value={data?.totalAccounts || 0} color="#6C63FF" to="/accounts" />
        <StatCard icon={<FiCheckCircle />} label="মোট পোস্ট" value={data?.postStats?.total || 0} color="#43E97B" to="/history" />
        <StatCard icon={<FiClock />} label="শিডিউল অপেক্ষায়" value={data?.totalScheduled || 0} color="#FFD93D" to="/schedule" />
        <StatCard icon={<FiFolder />} label="আপলোড করা ফাইল" value={data?.totalUploads || 0} color="#FF6584" to="/library" />
      </div>

      {/* Platform breakdown */}
      <div className="section-card">
        <h2 className="section-title"><FiTrendingUp /> প্ল্যাটফর্ম ওভারভিউ</h2>
        <div className="platforms-row">
          <PlatformBadge type="youtube" count={data?.platformStats?.youtube || 0} />
          <PlatformBadge type="instagram" count={data?.platformStats?.instagram || 0} />
          <PlatformBadge type="tiktok" count={data?.platformStats?.tiktok || 0} />
        </div>

        <div className="platform-bars">
          {[
            { type: 'youtube', color: '#FF0000', label: 'YouTube' },
            { type: 'instagram', color: '#E1306C', label: 'Instagram' },
            { type: 'tiktok', color: '#69C9D0', label: 'TikTok' },
          ].map(p => {
            const count = data?.platformStats?.[p.type] || 0;
            const max = data?.totalAccounts || 1;
            const pct = Math.round((count / max) * 100);
            return (
              <div key={p.type} className="platform-bar-row">
                <span style={{ color: p.color, width: 90 }}>{p.label}</span>
                <div className="bar-track">
                  <div className="bar-fill" style={{ width: `${pct}%`, background: p.color }} />
                </div>
                <span className="bar-count">{count}</span>
              </div>
            );
          })}
        </div>
      </div>

      <div className="dashboard-bottom">
        {/* Upcoming Scheduled */}
        <div className="section-card flex-1">
          <h2 className="section-title"><FiClock /> আসন্ন শিডিউল</h2>
          {data?.upcomingScheduled?.length === 0 ? (
            <div className="empty-state">
              <FiClock size={32} />
              <p>কোনো শিডিউল নেই</p>
              <Link to="/schedule" className="btn-outline">শিডিউল করুন</Link>
            </div>
          ) : (
            <div className="activity-list">
              {data?.upcomingScheduled?.map(s => (
                <div key={s.id} className="activity-item">
                  <div className="activity-dot" style={{ background: '#FFD93D' }} />
                  <div className="activity-info">
                    <div className="activity-title">{s.title}</div>
                    <div className="activity-meta text-xs text-muted">
                      {format(new Date(s.scheduledAt), 'dd MMM yyyy, hh:mm a')}
                      {' · '}{s.accountIds?.length} অ্যাকাউন্ট
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Recent Activity */}
        <div className="section-card flex-1">
          <h2 className="section-title"><FiCheckCircle /> সাম্প্রতিক পোস্ট</h2>
          {data?.recentActivity?.length === 0 ? (
            <div className="empty-state">
              <FiPlusSquare size={32} />
              <p>এখনো কোনো পোস্ট নেই</p>
              <Link to="/create" className="btn-outline">পোস্ট করুন</Link>
            </div>
          ) : (
            <div className="activity-list">
              {data?.recentActivity?.map(p => (
                <div key={p.id} className="activity-item">
                  <div className="activity-dot" style={{
                    background: p.status === 'published' ? '#43E97B' : p.status === 'partial' ? '#FFD93D' : '#FF6584'
                  }} />
                  <div className="activity-info">
                    <div className="activity-title">{p.title}</div>
                    <div className="activity-meta text-xs text-muted">
                      {p.publishedAt ? format(new Date(p.publishedAt), 'dd MMM, hh:mm a') : '—'}
                      {' · '}
                      <span style={{ color: p.status === 'published' ? '#43E97B' : '#FF6584' }}>
                        {p.status === 'published' ? '✓ সফল' : p.status === 'partial' ? '⚠ আংশিক' : '✕ ব্যর্থ'}
                      </span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
