import React, { createContext, useContext, useState, useCallback, useEffect } from 'react';
import axios from 'axios';
import { handleMockApi, initMockData } from '../utils/mockStorage';

const AuthContext = createContext(null);

// If port is 3000, target 5000 directly for API; otherwise use relative /api
const getBaseURL = () => {
  if (typeof window !== 'undefined' && window.location.port === '3000') {
    return 'http://localhost:5000/api';
  }
  return '/api';
};

const API = axios.create({
  baseURL: getBaseURL(),
  timeout: 5000
});

// Request interceptor
API.interceptors.request.use(config => {
  const t = localStorage.getItem('smm_token');
  if (t) config.headers.Authorization = `Bearer ${t}`;
  return config;
});

// Response interceptor with graceful fallback
API.interceptors.response.use(
  res => res,
  async error => {
    console.warn('API error encountered, activating mock fallback:', error.message);
    try {
      const fallbackData = await handleMockApi(error.config || {});
      if (fallbackData !== null) {
        return {
          data: fallbackData,
          status: 200,
          statusText: 'OK',
          headers: {},
          config: error.config
        };
      }
    } catch (fallbackErr) {
      console.error('Fallback error:', fallbackErr);
    }
    return Promise.reject(error);
  }
);

export function AuthProvider({ children }) {
  useEffect(() => {
    initMockData();
  }, []);

  const [token, setToken] = useState(() => localStorage.getItem('smm_token'));
  const [user, setUser] = useState(() => {
    try { return JSON.parse(localStorage.getItem('smm_user')); } catch { return null; }
  });

  const login = useCallback(async (username, password) => {
    try {
      const res = await API.post('/auth/login', { username, password });
      const { token: t, user: u } = res.data;
      setToken(t);
      setUser(u);
      localStorage.setItem('smm_token', t);
      localStorage.setItem('smm_user', JSON.stringify(u));
      return u;
    } catch {
      // Local fallback login
      const fallback = await handleMockApi({ url: '/auth/login', method: 'post', data: { username, password } });
      const { token: t, user: u } = fallback;
      setToken(t);
      setUser(u);
      localStorage.setItem('smm_token', t);
      localStorage.setItem('smm_user', JSON.stringify(u));
      return u;
    }
  }, []);

  const logout = useCallback(() => {
    setToken(null);
    setUser(null);
    localStorage.removeItem('smm_token');
    localStorage.removeItem('smm_user');
  }, []);

  return (
    <AuthContext.Provider value={{ token, user, login, logout, api: API }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}
