import React, { useEffect, useState, useCallback } from 'react';
import { useApi } from '../hooks/useApi';
import { toast } from 'react-toastify';
import { FiFolder, FiTrash2, FiVideo, FiImage, FiUploadCloud, FiRefreshCw } from 'react-icons/fi';
import { useDropzone } from 'react-dropzone';
import { format } from 'date-fns';
import './Library.css';

function UploadZone({ onUpload }) {
  const [uploading, setUploading] = useState(false);
  const api = useApi();

  const onDrop = useCallback(async (files) => {
    if (!files.length) return;
    setUploading(true);
    try {
      const formData = new FormData();
      files.forEach(f => formData.append('files', f));
      await api.post('/upload', formData, { headers: { 'Content-Type': 'multipart/form-data' } });
      toast.success(`${files.length}টি ফাইল আপলোড হয়েছে`);
      onUpload();
    } catch { toast.error('আপলোড ব্যর্থ'); }
    finally { setUploading(false); }
  }, [api, onUpload]);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: { 'video/*': [], 'image/*': [] },
    multiple: true,
    maxSize: 500 * 1024 * 1024
  });

  return (
    <div {...getRootProps()} className={`dropzone ${isDragActive ? 'active' : ''} ${uploading ? 'uploading' : ''}`}>
      <input {...getInputProps()} />
      <div className="dropzone-inner">
        <FiUploadCloud size={36} />
        {uploading ? (
          <><div className="spinner sm" /><p>আপলোড হচ্ছে...</p></>
        ) : (
          <><p>{isDragActive ? 'ছেড়ে দিন!' : 'ভিডিও ও ছবি আপলোড করুন'}</p>
          <span className="text-muted text-xs">একসাথে অনেক ফাইল / সর্বোচ্চ 500MB</span></>
        )}
      </div>
    </div>
  );
}

function FileCard({ file, onDelete }) {
  const isVideo = file.mimetype?.startsWith('video');
  const sizeMB = (file.size / (1024 * 1024)).toFixed(1);

  return (
    <div className="file-card animate-fadein">
      <div className="file-preview">
        {isVideo ? (
          <video src={file.path} className="preview-video" />
        ) : (
          <img src={file.path} alt={file.originalName} className="preview-img" />
        )}
        <div className="file-type-badge">
          {isVideo ? <FiVideo /> : <FiImage />}
        </div>
      </div>
      <div className="file-card-info">
        <div className="file-card-name">{file.originalName}</div>
        <div className="file-card-meta text-xs text-muted">
          {sizeMB} MB · {format(new Date(file.uploadedAt), 'dd MMM yyyy')}
        </div>
      </div>
      <button className="icon-btn danger file-delete" onClick={() => onDelete(file.id, file.originalName)}>
        <FiTrash2 />
      </button>
    </div>
  );
}

export default function Library() {
  const api = useApi();
  const [files, setFiles] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [search, setSearch] = useState('');

  const fetchFiles = useCallback(() => {
    setLoading(true);
    api.get('/upload')
      .then(r => setFiles(r.data.files))
      .catch(() => toast.error('লোড ব্যর্থ'))
      .finally(() => setLoading(false));
  }, [api]);

  useEffect(() => { fetchFiles(); }, [fetchFiles]);

  const handleDelete = async (id, name) => {
    if (!window.confirm(`"${name}" মুছবেন?`)) return;
    try {
      await api.delete(`/upload/${id}`);
      toast.success('ফাইল মুছা হয়েছে');
      setFiles(f => f.filter(x => x.id !== id));
    } catch { toast.error('মুছতে সমস্যা'); }
  };

  const filtered = files
    .filter(f => filter === 'all' || (filter === 'video' ? f.mimetype?.startsWith('video') : f.mimetype?.startsWith('image')))
    .filter(f => !search || f.originalName.toLowerCase().includes(search.toLowerCase()));

  const totalSize = (files.reduce((acc, f) => acc + (f.size || 0), 0) / (1024 * 1024)).toFixed(1);

  return (
    <div className="library-page animate-fadein">
      <div className="page-header">
        <div>
          <h1 className="page-title">মিডিয়া লাইব্রেরি</h1>
          <p className="text-muted">{files.length}টি ফাইল · মোট {totalSize} MB</p>
        </div>
        <button className="btn-outline" onClick={fetchFiles}><FiRefreshCw /> রিফ্রেশ</button>
      </div>

      <UploadZone onUpload={fetchFiles} />

      <div className="library-controls">
        <div className="filter-row">
          {[
            { key: 'all', label: 'সব' },
            { key: 'video', label: '🎬 ভিডিও' },
            { key: 'image', label: '🖼️ ছবি' },
          ].map(f => (
            <button key={f.key} className={`filter-chip ${filter === f.key ? 'active' : ''}`}
              style={{ '--c': '#6C63FF' }} onClick={() => setFilter(f.key)}>
              {f.label}
            </button>
          ))}
        </div>
        <input
          className="input search-input"
          placeholder="ফাইল খুঁজুন..."
          value={search}
          onChange={e => setSearch(e.target.value)}
        />
      </div>

      {loading ? (
        <div className="loading-center"><div className="spinner" /></div>
      ) : filtered.length === 0 ? (
        <div className="empty-state section-card">
          <FiFolder size={48} style={{ opacity: 0.3 }} />
          <p>{search ? 'কোনো ফাইল পাওয়া যায়নি' : 'এখনো কোনো ফাইল নেই'}</p>
        </div>
      ) : (
        <div className="files-grid">
          {filtered.map(f => (
            <FileCard key={f.id} file={f} onDelete={handleDelete} />
          ))}
        </div>
      )}
    </div>
  );
}
