import React, { useState } from 'react';
import { Outlet, NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import {
  FiGrid, FiUsers, FiPlusSquare, FiClock, FiFolder, FiList,
  FiLogOut, FiMenu, FiX, FiYoutube
} from 'react-icons/fi';
import { FaTiktok, FaInstagram } from 'react-icons/fa';
import './Layout.css';

const navItems = [
  { to: '/', icon: <FiGrid />, label: 'ড্যাশবোর্ড', end: true },
  { to: '/accounts', icon: <FiUsers />, label: 'অ্যাকাউন্টস' },
  { to: '/create', icon: <FiPlusSquare />, label: 'পোস্ট করুন' },
  { to: '/schedule', icon: <FiClock />, label: 'শিডিউল' },
  { to: '/library', icon: <FiFolder />, label: 'মিডিয়া লাইব্রেরি' },
  { to: '/history', icon: <FiList />, label: 'পোস্ট হিস্ট্রি' },
];

export default function Layout() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [sidebarOpen, setSidebarOpen] = useState(false);

  const handleLogout = () => { logout(); navigate('/login'); };

  return (
    <div className="layout">
      {/* Mobile overlay */}
      {sidebarOpen && <div className="sidebar-overlay" onClick={() => setSidebarOpen(false)} />}

      {/* Sidebar */}
      <aside className={`sidebar ${sidebarOpen ? 'open' : ''}`}>
        <div className="sidebar-header">
          <div className="logo">
            <span className="logo-icon">
              <FiYoutube style={{ color: '#FF0000' }} />
              <FaInstagram style={{ color: '#E1306C' }} />
              <FaTiktok style={{ color: '#69C9D0' }} />
            </span>
            <span className="logo-text gradient-text">SocialHub</span>
          </div>
          <button className="sidebar-close" onClick={() => setSidebarOpen(false)}>
            <FiX />
          </button>
        </div>

        <nav className="sidebar-nav">
          {navItems.map(item => (
            <NavLink
              key={item.to}
              to={item.to}
              end={item.end}
              className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`}
              onClick={() => setSidebarOpen(false)}
            >
              <span className="nav-icon">{item.icon}</span>
              <span className="nav-label">{item.label}</span>
            </NavLink>
          ))}
        </nav>

        <div className="sidebar-footer">
          <div className="user-info">
            <div className="user-avatar">{user?.username?.[0]?.toUpperCase()}</div>
            <div>
              <div className="user-name">{user?.username}</div>
              <div className="user-role text-xs text-muted">Admin</div>
            </div>
          </div>
          <button className="btn-logout" onClick={handleLogout} title="লগআউট">
            <FiLogOut />
          </button>
        </div>
      </aside>

      {/* Main */}
      <div className="main-wrapper">
        <header className="topbar">
          <button className="menu-btn" onClick={() => setSidebarOpen(true)}>
            <FiMenu />
          </button>
          <div className="topbar-title gradient-text">SocialHub</div>
          <div className="topbar-right">
            <div className="user-avatar sm">{user?.username?.[0]?.toUpperCase()}</div>
          </div>
        </header>

        <main className="main-content">
          <Outlet />
        </main>
      </div>
    </div>
  );
}
